@Injectable()
export class PermissionsGuard extends RolesGuard {
  constructor(@Inject(ROLE_RESOLVER) protected resolver: RoleResolver) {
    super(resolver);
  }

  async canActivate(context: any) {
    const req = context.switchToHttp().getRequest<Request>();
    const userRoles = await this.resolve(req.user.role);

    if (!userRoles.includes(this.permission)) {
      return false;
    }

    return super.canActivate(context);
  }
}

interface RoleResolver {
  resolve(userRole: string): Promise<string[]>;
}
